{"file_text": "@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <h3 class="mb-3">Product Catalog</h3>

    @if (_error is not null)
    {
        <div class="alert alert-danger" role="alert">
            <strong>Error:</strong> @_error
            <button class="btn btn-sm btn-outline-danger ms-2" @onclick="RetryAsync">Retry</button>
        </div>
    }
    else
    {
        <div class="row">
            @* ── Left sidebar ── *@
            <div class="col-lg-3 mb-3">
                <CatalogFilters Categories="_categories"
                                OnApply="HandleApplyFilters"
                                OnClear="HandleClearFilters" />
            </div>

            @* ── Main content ── *@
            <div class="col-lg-9">
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div class="d-flex align-items-center gap-2">
                        <label class="form-label mb-0 fw-semibold" for="sortSelect">Sort by:</label>
                        <select id="sortSelect" class="form-select form-select-sm w-auto"
                                value="@_sortBy"
                                @onchange="HandleSortChanged">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A–Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </div>
                    <span class="text-muted">
                        @if (_result is not null && _result.TotalCount > 0)
                        {
                            var start = (_result.Page - 1) * _result.PageSize + 1;
                            var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                            @($"Showing {start}–{end} of {_result.TotalCount} products")
                        }
                    </span>
                </div>

                @if (_loading)
                {
                    <div class="d-flex justify-content-center py-5">
                        <div class="spinner-border text-primary" role="status">
                            <span class="visually-hidden">Loading...</span>
                        </div>
                    </div>
                }
                else if (_result is null || _result.Items.Count == 0)
                {
                    <div class="text-center py-5 text-muted">
                        <h5>No products found</h5>
                        <p>Try adjusting your filters.</p>
                    </div>
                }
                else
                {
                    @* Product grid *@
                    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-3 mb-3">
                        @foreach (var product in _result.Items)
                        {
                            <div class="col">
                                <ProductCard Product="product"
                                             OnProductSelected="HandleProductSelected"
                                             OnAddToCart="HandleAddToCart" />
                            </div>
                        }
                    </div>

                    @* Pagination *@
                    @if (TotalPages > 1)
                    {
                        <nav aria-label="Product pagination">
                            <ul class="pagination justify-content-center">
                                <li class="page-item @(_page <= 1 ? "disabled" : "")">
                                    <button class="page-link" disabled="@(_page <= 1)"
                                            @onclick="() => GoToPage(_page - 1)">Previous</button>
                                </li>
                                @foreach (var p in PageNumbers)
                                {
                                    <li class="page-item @(p == _page ? "active" : "")">
                                        <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
                                    </li>
                                }
                                <li class="page-item @(_page >= TotalPages ? "disabled" : "")">
                                    <button class="page-link" disabled="@(_page >= TotalPages)"
                                            @onclick="() => GoToPage(_page + 1)">Next</button>
                                </li>
                            </ul>
                        </nav>
                    }
                }
            </div>
        </div>
    }
</div>

